mapper.select:
select id, kb_id, doc_key, subject_id, chapter_id, source_type, title, section_path, source_uri,
       page_start, page_end, chunk_count, token_count, content_hash, status, version, tags,
       create_time, update_time
from kb_document

     and subject_id = #{subjectId}
     and chapter_id = #{chapterId}
     and source_type = #{sourceType}

order by id asc

mapper.delete:
delete from kb_document



        and 1 = 0

     and subject_id = #{subjectId}
     and chapter_id = #{chapterId}
     and source_type = #{sourceType}
